def closest_integer(value):
    num = float(value)

    if num == float('inf'):
        return float('inf')
    elif num == float('-inf'):
        return float('-inf')
    elif num != num:  # This checks for NaN
        return 0
    elif num == 0:
        return 0

    lower = int(num // 1)
    upper = lower + 1

    if abs(num - lower) < 0.5:
        return lower
    elif abs(num - upper) < 0.5:
        return upper
    elif num > 0:
        return upper
    else:
        return lower

